import React from "react";

function Projects() {
  return (
    <section id="projects" className="projects">

      <h2>Projects</h2>

      <div className="project-grid">

        <div className="card">
          <h3>Visitor Management System</h3>
          <p>PHP + MySQL</p>
        </div>

        <div className="card">
          <h3>Cake Order System</h3>
          <p>JavaScript + PHP</p>
        </div>

        <div className="card">
          <h3>React Portfolio</h3>
          <p>React + CSS</p>
        </div>

      </div>

    </section>
  );
}

export default Projects;
